namespace Orb.Automate.Agents.HR.Api.Contracts;

/// <summary>
/// Represents the completed response returned by the chat agent.
/// </summary>
/// <param name="Message">The response text generated by the agent.</param>
/// <param name="ResponseId">The provider response identifier, when available.</param>
/// <param name="FinishReason">The reason the provider completed the response, when available.</param>
/// <param name="Citations">The retrieved sources explicitly cited by the response.</param>
/// <param name="EmailDraft">
/// A structured email draft produced by the agent when the user's request cannot be fulfilled
/// directly and the agent offers to help compose an email instead. Null for ordinary responses.
/// </param>
/// <param name="SmartObjective">
/// A structured SMART performance objective produced by the agent when the user asked for help
/// writing or refining a performance/MYCD objective. Null for ordinary responses.
/// </param>
public sealed record ChatResponse(
    string Message,
    string? ResponseId,
    string? FinishReason,
    IReadOnlyList<ChatCitation>? Citations = null,
    EmailDraft? EmailDraft = null,
    SmartObjective? SmartObjective = null);

/// <summary>
/// A citation validated against the controlled grounding ledger for one response.
/// </summary>
/// <param name="RetrievalId">The stable chunk identifier from the retrieval result.</param>
/// <param name="ParentId">The source-document identifier.</param>
/// <param name="Title">The canonical source title.</param>
/// <param name="Url">The canonical SharePoint URL.</param>
/// <param name="Score">The semantic reranker score used to select the passage.</param>
/// <param name="SourceVersion">The indexed source version, when available.</param>
/// <param name="LastModified">The indexed source modification time, when available.</param>
/// <param name="SourceSystem">The controlled source-system name.</param>
/// <param name="SitePath">The source location shown by the analytics dashboard.</param>
/// <param name="KbNumber">The ServiceNow KB number, when applicable.</param>
/// <param name="FreshnessFlag">Whether the source is current or stale.</param>
public sealed record ChatCitation(
    string RetrievalId,
    string ParentId,
    string Title,
    string Url,
    double Score,
    string SourceVersion,
    DateTimeOffset? LastModified,
    string SourceSystem = "Sphere",
    string SitePath = "Sphere > HR Policies",
    string KbNumber = "",
    string FreshnessFlag = "Current");

/// <summary>
/// A structured email draft produced by the agent when it cannot fulfil a request directly.
/// The agent composes a ready-to-send email the user can copy, edit, and send themselves.
/// </summary>
/// <param name="Subject">The proposed email subject line.</param>
/// <param name="Body">The full email body text, formatted as plain text with line breaks.</param>
/// <param name="SuggestedRecipient">
/// A human-readable description of the suggested recipient (e.g. "your HR Business Partner"
/// or "your line manager"). Never a personal email address.
/// </param>
/// <param name="Tone">
/// The tone applied to the draft. One of: <c>professional</c>, <c>empathetic</c>, <c>factual</c>.
/// </param>
/// <param name="PolicySourceUrls">
/// Exact canonical URLs from the grounding ledger that informed the draft content.
/// Mirrors the citation URLs in the parent <see cref="ChatResponse"/>.
/// </param>
public sealed record EmailDraft(
    string Subject,
    string Body,
    string? SuggestedRecipient,
    string Tone,
    IReadOnlyList<string>? PolicySourceUrls = null);

/// <summary>
/// A structured SMART performance objective produced by the agent, checked against the
/// company's SMART rubric: specific, measurable, achievable, relevant, and time-bound.
/// </summary>
/// <param name="ObjectiveText">
/// The full objective statement, written so the employee or manager can copy it directly
/// into their performance/MYCD record (e.g. Workday).
/// </param>
/// <param name="Specific">A short note on what makes the objective specific, when available.</param>
/// <param name="Measurable">
/// A short note on how progress or success is measured (a number, metric, or observable outcome),
/// when available.
/// </param>
/// <param name="Achievable">A short note on why the objective is realistic for the role, when available.</param>
/// <param name="Relevant">
/// A short note tying the objective to the employee's role or business priorities, when available.
/// </param>
/// <param name="TimeBound">The deadline or period the objective must be completed within, when available.</param>
/// <param name="PolicySourceUrls">
/// Exact canonical URLs from the grounding ledger that informed the objective (e.g. the official
/// "how to set SMART objectives" guidance), when policy content was used. Mirrors the citation
/// URLs in the parent <see cref="ChatResponse"/>.
/// </param>
public sealed record SmartObjective(
    string ObjectiveText,
    string? Specific = null,
    string? Measurable = null,
    string? Achievable = null,
    string? Relevant = null,
    string? TimeBound = null,
    IReadOnlyList<string>? PolicySourceUrls = null);

/// <summary>
/// Represents a streamed update emitted while the agent is generating a response.
/// </summary>
/// <param name="Text">The response text for this update.</param>
/// <param name="ResponseId">The provider response identifier, when available.</param>
/// <param name="EmailDraft">
/// A structured email draft when the completed response contained a valid
/// <c>email-draft</c> fence. Populated on the final stream event once the response is complete.
/// </param>
/// <param name="SmartObjective">
/// A structured SMART objective when the completed response contained a valid
/// <c>smart-objective</c> fence. Populated on the final stream event once the response is complete.
/// </param>
public sealed record ChatStreamUpdate(
    string Text,
    string? ResponseId,
    EmailDraft? EmailDraft = null,
    SmartObjective? SmartObjective = null);
